// Inner join: orders without a known customer are dropped.
var rows = orders.Join(customers, o => o.CustomerId, c => c.Id,
    (o, c) => new { o.Id, c.Name });

// GroupJoin: every customer, with their orders (maybe none).
var perCustomer = customers.GroupJoin(orders, c => c.Id, o => o.CustomerId,
    (c, os) => new { c.Name, OrderCount = os.Count() });

// Left join, flattened: one row per order, or one row with null for no orders.
var left = customers
    .GroupJoin(orders, c => c.Id, o => o.CustomerId, (c, os) => new { c, os })
    .SelectMany(x => x.os.DefaultIfEmpty(), (x, o) => new { x.c.Name, OrderId = o?.Id });

// Flatten, then group.
var unitsPerSku = orders
    .SelectMany(o => o.Lines)
    .GroupBy(line => line.Sku)
    .Select(g => new { Sku = g.Key, Units = g.Sum(l => l.Quantity) })
    .OrderByDescending(x => x.Units).ThenBy(x => x.Sku);
